namespace {
void retained(const SculptObject &a,const SculptObject &b){
 demand(a.material_bindings->native_paint_frames==b.material_bindings->native_paint_frames&&a.material_bindings->normal_frames==b.material_bindings->normal_frames&&a.material_bindings->uv_origin==b.material_bindings->uv_origin&&a.rig_source==b.rig_source&&a.shape_source==b.shape_source,"Post-key UV retains independent current normal capture and original rig/shape capsules");
 demand(a.painted->layers().size()==b.painted->layers().size(),"Post-key UV retains every native editable layer");for(size_t n=0;n<a.painted->layers().size();++n){const auto&x=a.painted->layers()[n],&y=b.painted->layers()[n];demand(x.id==y.id&&x.name==y.name&&x.visible==y.visible&&x.opacity==y.opacity&&x.tiles==y.tiles&&x.pbr_tiles==y.pbr_tiles&&x.emission_tiles==y.emission_tiles,"Post-key UV retains exact layer/mask/common/PBR/emission pixel owners and metadata");}
 auto old=a.deformation->preview(a.painted->mesh()),now=b.deformation->preview(b.painted->mesh());demand(old.indices.size()==now.indices.size(),"Current posed triangles remain complete");for(size_t c=0;c<old.indices.size();++c){const auto p=old.positions[old.indices[c]],q=now.positions[now.indices[c]];demand(p.x==q.x&&p.y==q.y&&p.z==q.z,"Post-key UV preserves actual posed corner POSITION exactly");}
 detail::normal_frame_current_authority(*b.material_bindings,b.painted->mesh(),b.deformation.get());
}
}
int main(int argc,char**argv)try{if(argc!=2)return 2;const std::filesystem::path out=argv[1];std::filesystem::create_directories(out);setenv("XDG_STATE_HOME",(out/"state").c_str(),1);setenv("XDG_CONFIG_HOME",(out/"config").c_str(),1);
 auto input=with_reference(native_case(false));author_skin(input.scene,input.target,input.options);const auto original_shape=input.scene.encode();ShapeKeyEdit key;key.name="Current seam key";author_shapekey(input.scene,input.target,key);key.action=ShapeKeyAction::Replace;key.target=0;key.positions=input.scene.active().painted->mesh().positions;key.positions[0].z+=.01f;author_shapekey(input.scene,input.target,key);
 auto d=std::make_shared<DeformationState>(*input.scene.active().deformation);d->morph_weights={.35f};for(const auto&b:d->skeleton->bones)d->pose.push_back(b.rest);d->pose[1].rotation=arcball({0,1,0},{.3f,.9539392f,0});input.scene.active().deformation=d;input.scene.validate();const auto before=input.scene.encode();input.scene.save(out/"before.dsculpt");const auto source=input.scene.active();
 demand(detail::native_paint_retention_supported(source),"Genuine paired native key/frame is eligible for owning UV model transfer");auto target=source.painted->mesh();std::vector<uint32_t>map(target.positions.size());std::iota(map.rbegin(),map.rend(),0u);std::vector<uint32_t>inverse(map.size());for(size_t v=0;v<map.size();++v){inverse[map[v]]=v;target.positions[v]=source.painted->mesh().positions[map[v]];target.normals[v]=source.painted->mesh().normals[map[v]];const auto uv=source.painted->mesh().uv[map[v]];target.uv[v]={.5f-.8f*(uv[1]-.5f),.5f+.8f*(uv[0]-.5f)};}for(size_t c=0;c<target.indices.size();++c)target.indices[c]=inverse[source.painted->mesh().indices[c]];
 auto result=detail::retain_native_paint_model(source,target,map);auto mapped=input.scene;mapped.active().painted=result.sampling.paint;mapped.active().material_bindings=detail::bind_native_paint(result.sampling.owner,source.material_bindings);mapped.active().deformation=result.deformation;mapped.validate();retained(source,mapped.active());for(size_t v=0;v<map.size();++v)demand(mapped.active().deformation->morphs->targets[0].delta[v].z==source.deformation->morphs->targets[0].delta[map[v]].z,"Exact source vertex remap preserves independent seam morph values");
 {auto wrong=map;std::swap(wrong[0],wrong[1]);demand(denied([&]{detail::retain_native_paint_model(source,target,wrong);})&&input.scene.encode()==before,"Reordered source corners cannot borrow a count-equal native frame/paint mapping");}
 {auto bad=source;auto altered=std::make_shared<DeformationState>(*bad.deformation);altered->morphs->targets[0].delta[0].z+=.001f;bad.deformation=altered;demand(denied([&]{detail::retain_native_paint_model(bad,target,map);})&&input.scene.encode()==before,"UV worker authenticates current morph geometry before accepting the sealed frame owner");}
 for(unsigned kind=0;kind<4;++kind){PaintSamplingLimits limits;if(kind==0)limits.max_working_bytes=1;if(kind==1)limits.max_work=1;if(kind==2)limits.max_basis_bytes=1;if(kind==3)limits.cancelled=[] {return true;};demand(denied([&]{detail::retain_native_paint_model(source,target,map,limits);})&&input.scene.encode()==before,"Bounded paint/model preparation and cancellation preserve the complete caller before publication");}
 Document doc;doc.replace(input.scene);ready(doc);doc.begin_uv();demand(doc.wait_uv()&&doc.frame().state->uv->paint_sampling_available,"Actual post-key UV offers its genuine paired retention route");doc.edit_uv(UvAction::Pick,.5f,.5f);doc.edit_uv(UvAction::Scale,.8f);doc.edit_uv(UvAction::Rotate,.3f);demand(doc.wait_uv()&&doc.frame().state->uv->valid,"Actual post-key UV draft validates");doc.end_uv(true);doc.save_async(out/"key-uv.dsculpt").get();ready(doc);auto after=doc.copy_scene();retained(source,after.active());demand(Scene::load(out/"key-uv.dsculpt").encode()==after.encode(),"Actual post-key UV Save/reopen retains the complete frame/paint/model DAG");demand(doc.undo()&&doc.copy_scene().encode()==before&&!doc.frame().state->can_undo&&doc.redo()&&doc.copy_scene().encode()==after.encode(),"Actual post-key UV owns exactly one complete Undo/Redo endpoint");
 doc.begin_uv();demand(doc.wait_uv(),"Post-key UV Cancel is ready");doc.edit_uv(UvAction::Scale,.9f);doc.end_uv(false);demand(doc.copy_scene().encode()==after.encode(),"Post-key UV Cancel preserves every independent field and source");
 ShapeKeyEdit next;next.name="After true current UV";doc.author_shape(next);doc.save_async(out/"key-after-uv.dsculpt").get();ready(doc);const auto added=doc.copy_scene();std::cout<<"KEY_AFTER_UV count="<<added.active().deformation->morphs->targets.size()<<" prior="<<after.active().deformation->morphs->targets.size()<<" rig="<<(added.active().rig_source==after.active().rig_source)<<" shape="<<(added.active().shape_source==after.active().shape_source)<<" deltaCount="<<added.active().deformation->morphs->targets[0].delta.size()<<"/"<<after.active().deformation->morphs->targets[0].delta.size()<<std::endl;demand(added.active().deformation->morphs->targets.size()==2&&std::equal(added.active().deformation->morphs->targets[0].delta.begin(),added.active().deformation->morphs->targets[0].delta.end(),after.active().deformation->morphs->targets[0].delta.begin(),[](Vec3 a,Vec3 b){return a.x==b.x&&a.y==b.y&&a.z==b.z;})&&added.active().rig_source==after.active().rig_source&&added.active().shape_source==after.active().shape_source,"Actual key authoring after UV retains the earlier independent seam key and first rig/shape source");demand(Scene::load(out/"key-after-uv.dsculpt").encode()==added.encode()&&doc.undo()&&doc.copy_scene().encode()==after.encode()&&doc.redo()&&doc.copy_scene().encode()==added.encode(),"Post-UV key owns one accepted Save/Undo endpoint and fully replays after restart");
 ShapeKeyEdit restore;restore.action=ShapeKeyAction::Restore;doc.author_shape(restore);doc.save_async(out/"full-shape-source.dsculpt").get();ready(doc);demand(doc.copy_scene().encode()==original_shape&&Scene::load(out/"full-shape-source.dsculpt").encode()==original_shape&&doc.undo()&&doc.copy_scene().encode()==added.encode()&&doc.redo(),"After key/UV/new-key authoring full Shape Restore recovers the authentic first native paint/skin capsule with exact history and Save");
 std::cout<<"PASS native_key_uv_checks="<<rig_checks<<std::endl;return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
